UPDATE order_return_shipment SET shipment_status=#{row.shipmentStatus},tracking_no=#{row.trackingNo},carrier_name=#{row.carrierName},remark=#{row.remark},
    sent_at=#{row.sentAt},expected_arrival_at=#{row.expectedArrivalAt},expected_check_start_at=#{row.expectedCheckStartAt},version=version+1,updated_at=#{row.updatedAt}
    WHERE id=#{row.id} AND rental_order_id=#{row.rentalOrderId} AND version=#{version} AND shipment_status='draft'
